public static int findNthLeapYear(int Y, int N) {
        // Validate inputs
        if (Y < 0) {
            throw new IllegalArgumentException("Year Y must be non-negative.");
        }
        if (N <= 0) {
            throw new IllegalArgumentException("N must be a positive integer.");
        }

        int currentYear = Y + 1; // Since we need leap years AFTER Y
        int count = 0;

        while (count < N) {
            if (isLeapYear(currentYear)) {
                count++;
            }
            currentYear++;
        }

        // The loop exits when count == N.
        // The leap year found was at currentYear - 1.
        return currentYear - 1;
    }

public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers.");
    }

    int year = Y;
    int count = 0;

    while (count < N) {
        year++;
        if (isLeapYear(year)) {
            count++;
        }
    }

    return year;
}

public static int findNthLeapYear(int Y, int N) {
    // Validate inputs
    if (N <= 0) {
        throw new IllegalArgumentException("N must be a positive integer.");
    }

    int count = 0;
    int year = Y;

    // We need to find the Nth leap year AFTER the start year Y.
    // So we start checking from Y+1.
    year = Y + 1;

    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        if (count >= N) {
            return year;
        }
        year++;
    }

    // If we reach here, there's no solution found (shouldn't normally happen for valid input)
    return -1;
}

