        if (s == null) continue;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                String sub = s.substring(i, j + 1);
                allSubstrings.add(sub);
                allSubstrings.add(new StringBuilder(sub).reverse().toString());
                maxLen = Math.max(maxLen, sub.length());
            }
        }
    }

    Set<String> allInverses = new HashSet<>();
    for (String s : strings) {
        if (s == null) continue;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                allInverses.add(s.substring(i, j + 1));
            }
        }
    }

    int largest = 0;
    for (String sub : allSubstrings) {
        if (allInverses.contains(sub) || allSubstrings.contains(new StringBuilder(sub).reverse().toString())) {
            // Check if sub or its inverse is a substring of any string
            boolean found = false;
            for (String s : strings) {
                if (s == null) continue;
                if (s.contains(sub) || s.contains(new StringBuilder(sub).reverse().toString())) {
                    found = true;
                    break;
                }
            }
            if (found) {
                largest = Math.max(largest, sub.length());
            }
        }
    }

    return largest;
}

