                count++;
                // Mark the entire connected component as visited using BFS or DFS
                // Using DFS recursively could cause stack overflow for large grids, so use iterative BFS
                // Use a stack for iterative DFS
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;

                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int r = cell[0];
                    int c = cell[1];

                    for (int d = 0; d < 8; d++) {
                        int nr = r + rowDirs[d];
                        int nc = c + colDirs[d];

                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && 
                            grid[nr][nc] == '@' && !visited[nr][nc]) {
