public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n ||
        endX < 0 || endX >= n || endY < 0 || endY >= n) {
        return "cannot be travelled";
    }

    if (startX == endX && startY == endY) {
        return "can be travelled";
    }

    // Build adjacency list
    // n x n grid, node id = x * n + y
    int totalNodes = n * n;
    List<List<Integer>> adjacencyList = new ArrayList<>();
    for (int i = 0; i < totalNodes; i++) {
        adjacencyList.add(new ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int x1 = path[0];
            int y1 = path[1];
            int x2 = path[2];
            int y2 = path[3];

            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n ||
                x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }

            int node1 = x1 * n + y1;
            int node2 = x2 * n + y2;
            adjacencyList.get(node1).add(node2);
            adjacencyList.get(node2).add(node1);
        }
    }

    // BFS from start node to end node
    int startNode = startX * n + startY;
    int endNode = endX * n + endY;

    boolean[] visited = new boolean[totalNodes];
    Queue<Integer> queue = new LinkedList<>();
    visited[startNode] = true;
    queue.offer(startNode);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }

        for (int neighbor : adjacencyList.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || start.length != 2) {
        throw new IllegalArgumentException("Start coordinates must be of length 2.");
    }
    if (end == null || end.length != 2) {
        throw new IllegalArgumentException("End coordinates must be of length 2.");
    }

    // Check if starting coordinates are within the grid bounds
    boolean validStartInRange = start[0] >= 0 && start[0] < n && start[1] >= 0 && start[1] < n;
    // Check if ending coordinates are within the grid bounds
    boolean validEndInRange = end[0] >= 0 && end[0] < n && end[1] >= 0 && end[1] < n;

    if (!validStartInRange || !validEndInRange) {
        // If coordinates are out of bounds, no travel is possible.
        return "cannot be travelled";
    }

    // If the start and end coordinates are the same, no travel is required, so it is trivially possible.
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // To check if a path exists, we can build a graph and run a BFS or DFS.
    int[] rows = {0, 1, -1, 0};
    int[] cols = {1, 0, 0, -1};

    // Build an adjacency list for the grid
    Map<Long, List<Long>> graph = new HashMap<>();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            long key = ((long) i) * n + j;
            graph.put(key, new ArrayList<>());
        }
    }

    // Add edges based on the given paths
    if (paths != null) {
        for (int[] path : paths) {
            if (path.length != 4) {
                // Assume invalid path entry, skip it.
                continue;
            }
            int row1 = path[0];
            int col1 = path[1];
            int row2 = path[2];
            int col2 = path[3];

            // Check if the coordinates are within the grid
            boolean v1InRange = row1 >= 0 && row1 < n && col1 >= 0 && col1 < n;
            boolean v2InRange = row2 >= 0 && row2 < n && col2 >= 0 && col2 < n;

            if (v1InRange && v2InRange) {
                long node1 = ((long) row1) * n + col1;
                long node2 = ((long) row2) * n + col2;

                // The problem implies these are paths between adjacent intersections, 
                // so they should be undirected. We add bidirectional edges.
                graph.putIfAbsent(node1, new ArrayList<>());
                graph.putIfAbsent(node2, new ArrayList<>());

                // Avoid adding duplicate edges if the same path appears multiple times
                if (!graph.get(node1).contains(node2)) {
                    graph.get(node1).add(node2);
                }
                if (!graph.get(node2).contains(node1)) {
                    graph.get(node2).add(node1);
                }
            }
        }
    }

    // We need to check if a path exists from start to end. 
    // However, the standard grid traversal problems usually assume you can move to adjacent cells if there is a path between them.
    // Actually, the problem description is "paths between adjacent n-tersections", and `paths` are passed upon.
    // We only have edges if they are specified in the `paths` list.
    // Let's run a standard BFS/DFS on the graph we constructed.

    Set<Long> visited = new HashSet<>();
    Queue<Long> queue = new LinkedList<>();

    long startKey = ((long) start[0]) * n + start[1];
    long endKey = ((long) end[0]) * n + end[1];

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        long node = queue.poll();

        if (node == endKey) {
            return "can be travelled";
        }

        if (graph.containsKey(node)) {
            for (Long neighbor : graph.get(node)) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    int len1 = word1.length();
    int len2 = word2.length();
    int sumOfLengths = len1 + len2;

    if (sumOfLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    // Convert to uppercase for case-insensitive comparison
    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    // Count common letters
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : word1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }

    for (char c : word2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(freq1[i], freq2[i]);
    }

    // Calculate GCD for simplification
    int numerator = commonCount;
    int denominator = sumOfLengths;

    int gcd = gcd(numerator, denominator);

    numerator /= gcd;
    denominator /= gcd;

    StringBuilder result = new StringBuilder();
    result.append("appx(").append(word1.toLowerCase()).append(", ").append(word2.toLowerCase()).append(") = ");

    if (denominator == 1) {
        result.append(numerator);
    } else {
        result.append(numerator).append("/").append(denominator);
    }

    return result.toString();
}

