public double trimMean(int[] arr) {
    // Sort the array to easily remove the smallest and largest 5%
    java.util.Arrays.sort(arr);

    int n = arr.length;
    // Calculate the number of elements to remove from each end
    int removeCount = n / 20;

    double sum = 0;
    int remainingCount = 0;

    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
        remainingCount++;
    }

    return sum / remainingCount;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }

    // Create a copy to sort
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    // Number of elements to trim from each end
    int trimCount = n / 20; // 5% of n

    // Sum the remaining elements
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }

    // Count remaining elements
    int count = n - 2 * trimCount;

    // Calculate mean
    return (double) sum / count;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    int removeCount = n * 5 / 100;

    if (removeCount == 0) {
        long sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return (double) sum / n;
    }

    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    int start = removeCount;
    int end = n - removeCount - 1;

    long sum = 0;
    int count = 0;
    for (int i = start; i <= end; i++) {
        sum += sorted[i];
        count++;
    }

    return (double) sum / count;
}

public double trimMean(int[] arr) {
