    // Find and remove the smallest trimCount and largest trimCount elements
    // We can sort the array and then sum the middle elements
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    int start = trimCount;
    int end = n - trimCount;

    double sum = 0.0;
    int count = 0;
    for (int i = start; i < end; i++) {
        sum += sorted[i];
