}

public double trimMean(int[] arr) {
    // Sort the array
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    int n = sorted.length;
    // Calculate how many elements to remove from each end
    int removeCount = n * 5 / 100; // 5% of elements

    // Calculate the sum of the middle elements
    double sum = 0;
    int startIndex = removeCount;
    int endIndex = n - removeCount - 1;

    for (int i = startIndex; i <= endIndex; i++) {
        sum += sorted[i];
    }

    int count = endIndex - startIndex + 1;

    // Return the mean
    return sum / count;
}

public boolean canArrange(int[] arr, int k) {
        if (arr == null || arr.length == 0) {
            return true;
        }
        if (arr.length % 2 != 0) {
            return false;
        }
        if (k <= 0) {
            return false;
        }

        int[] remainderCounts = new int[k];
        for (int num : arr) {
            int mod = num % k;
            if (mod < 0) {
                mod += k;
            }
            remainderCounts[mod]++;
        }

        if (remainderCounts[0] % 2 != 0) {
            return false;
        }

        for (int i = 1; i <= k / 2; i++) {
            int complement = (k - i) % k;
            if (remainderCounts[i] != remainderCounts[complement]) {
                return false;
            }
        }

        return true;
    }

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] remCount = new int[k];

    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        remCount[rem]++;
    }

    // For remainder 0, count must be even
    if (remCount[0] % 2 != 0) {
        return false;
    }

    // For remainder i, the complement is (k - i) % k
    // Pair remCount[i] with remCount[k - i]
    for (int i = 1; i <= k / 2; i++) {
        int complement = (k - i) % k;
        if (i == complement) {
            // When i == k/2 (only when k is even), count must be even
            if (remCount[i] % 2 != 0) {
                return false;
            }
        } else {
            if (remCount[i] != remCount[complement]) {
                return false;
            }
        }
    }

    return true;
}

