public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        count[remainder]++;
    }

    if (count[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            if (count[i] % 2 != 0) {
                return false;
            }
        } else {
            if (count[i] != count[j]) {
                return false;
            }
        }
    }

    return true;
}

