public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list for the tree
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    // DFS function to compute the time needed to collect apples in the subtree rooted at node
    // Returns the total time (edges traversed) needed to collect all apples in the subtree and return to node
    // We use a parent parameter to avoid going back to the parent node
    int dfs(int node, int parent, java.util.List<java.util.List<Integer>> adj, boolean[] hasApple) {
        int totalTime = 0;
        for (int neighbor : adj.get(node)) {
            if (neighbor == parent) continue;
            int childTime = dfs(neighbor, node, adj, hasApple);
            // If the child subtree has any apples (childTime > 0) or the child node itself has an apple,
            // we need to go to the child and come back, which takes 2 time units (1 to go, 1 to return),
            // plus the time spent in the child's subtree.
            if (childTime > 0 || hasApple[neighbor]) {
                totalTime += childTime + 2;
            }
        }
        return totalTime;
    }

    return dfs(0, -1, adj, hasApple);
}

