    // We can reach step i from step i-1 or step i-2
    // cost[i] is paid when we step on i

    int n = cost.length;
    // dp[i] = min(dp[i-1], dp[i-2]) + cost[i]
    // But we want to reach the top, which is index n (beyond the last step)
    // So if we reach index n, we don't pay cost[n] (it doesn't exist)

    // Let's use iterative DP with O(1) space
    // prev2 = minimum cost to reach step i-2
    // prev1 = minimum cost to reach step i-1

    // Base cases:
    // To reach step 0, cost is 0 (you start there, but you pay cost[0] when you step on it? 
    // Actually, the problem says: "You can step on two staircases in one step. You will start from the step with index 0 or 1."
    // And "pay cost[i] and climb one or two steps to the next".
    // So the cost is paid when you are on the step.

    // Let me think again:
    // If you start at index 0, you pay cost[0], then you can go to index 1 (paying cost[1]) or index 2 (paying cost[2]).
    // The goal is to reach the top, which is beyond the last index.
    // So if the last index is n-1, the top is n.

    // Let dp[i] be the minimum cost to reach step i (and you have just stepped on i, so you've paid cost[i]).
    // Then to reach the top (index n), you can come from step n-1 (by climbing one step) or step n-2 (by climbing two steps).
    // Since you don't pay cost when you reach the top, the minimum cost to reach the top is min(dp[n-1], dp[n-2]).

    // But wait, if you are at step i, you pay cost[i]. Then:
    // dp[0] = cost[0]
    // dp[1] = cost[1]
    // dp[i] = min(dp[i-1], dp[i-2]) + cost[i] for i >= 2

    // Then the answer is min(dp[n-1], dp[n-2]) because from either of those steps you can reach the top.

    // Let me verify with example:
    // [10, 15, 20]
    // dp[0] = 10
    // dp[1] = 15
    // dp[2] = min(10, 15) + 20 = 10 + 20 = 30
    // Answer = min(dp[1], dp[2]) = min(15, 30) = 15. Correct.

    // Second example: [1, 100, 1, 1, 1, 100, 1, 1, 100, 1]
    // dp[0] = 1
    // dp[1] = 100
    // dp[2] = min(1, 100) + 1 = 2
    // dp[3] = min(100, 2) + 1 = 3
    // dp[4] = min(2, 3) + 1 = 3
    // dp[5] = min(3, 3) + 100 = 103
    // dp[6] = min(3, 103) + 1 = 4
    // dp[7] = min(103, 4) + 1 = 5
    // dp[8] = min(4, 5) + 100 = 104
    // dp[9] = min(5, 104) + 1 = 6
    // Answer = min(dp[8], dp[9]) = min(104, 6) = 6. Correct!

    if (n == 1) {
        return cost[0];
    }

    int prev2 = cost[0]; // dp[i-2]
    int prev1 = cost[1]; // dp[i-1]

    for (int i = 2; i < n; i++) {
        int current = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }

    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    int prev2 = 0;
    int prev1 = 0;

    for (int i = 2; i <= n; i++) {
        int current = Math.min(prev1 + (i - 1 < n ? cost[i - 1] : 0), prev2 + (i - 2 < n ? cost[i - 2] : 0));
        prev2 = prev1;
        prev1 = current;
    }

    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;
    if (cost.length == 1) return cost[0];

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

