public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }

    if (k > s.length()) {
        return false;
    }

    // Total number of binary strings of length k
    int required = 1 << k;

    // Early return if the string length is too short to contain all required substrings
    // The minimum length needed is required + k - 1
    if (s.length() < required + k - 1) {
        return false;
    }

    boolean[] seen = new boolean[required];
    int count = 0;
    int current = 0;

    // Rolling through the string to extract binary substrings of length k
    // We represent the substring as an integer for efficient hashing
    for (int i = 0; i < s.length(); i++) {
        // Add the new bit to the right side
        current = (current << 1) | (s.charAt(i) - '0');

        // If we have processed more than k characters, we need to mask out the bits
        // that are no longer in the window of length k
        if (i >= k) {
            current = current & (1 << k) - 1;
        }

        // Once we have exactly k characters in the window, we check if we've seen this substring
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                // If we have found all possible binary strings, we can return early
                if (count == required) {
                    return true;
                }
            }
        }
    }

    return count == required;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int n = s.length();
    int totalCombinations = 1 << k;
    boolean[] seen = new boolean[totalCombinations];
    int count = 0;

    // Initialize with the first bit string of length k
    int windowValue = 0;
    for (int i = 0; i < k; i++) {
        windowValue = (windowValue << 1) | (s.charAt(i) - '0');
    }

    if (!seen[windowValue]) {
        seen[windowValue] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < n; i++) {
        // Remove the leftmost bit and add the new rightmost bit
        windowValue = ((windowValue << 1) & ((1 << k) - 1)) | (s.charAt(i) - '0');

        if (!seen[windowValue]) {
            seen[windowValue] = true;
            count++;
        }

        // Early termination if we've seen all combinations
        if (count == totalCombinations) {
            return true;
        }
    }

    return count == totalCombinations;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    if (s.length() < k) return false;

    int needed = 1 << k;
    boolean[] seen = new boolean[needed];
    int count = 0;

    int left = 0;
    for (int i = 0; i < s.length(); i++) {
        if (i - left == k) {
            left++;
        }
        int val = 0;
        for (int j = left; j <= i; j++) {
            val = val << 1;
            if (s.charAt(j) == '1') {
                val |= 1;
            }
        }
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == needed) {
                return true;
            }
        }
    }

    return count == needed;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int totalNeeded = 1 << k; // 2^k
    boolean[] seen = new boolean[totalNeeded];
    int seenCount = 0;

    // Start with the first k-length substring
    int currentCode = 0;
    for (int i = 0; i < k; i++) {
        currentCode = (currentCode << 1) | (s.charAt(i) - '0');
    }

    if (!seen[currentCode]) {
        seen[currentCode] = true;
        seenCount++;
        if (seenCount == totalNeeded) {
            return true;
        }
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        // Shift left and add new bit
        currentCode = ((currentCode << 1) | (s.charAt(i) - '0')) & (totalNeeded - 1);

        if (!seen[currentCode]) {
            seen[currentCode] = true;
            seenCount++;
            if (seenCount == totalNeeded) {
                return true;
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    if (s == null || s.length() < k) return false;

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    // Build the initial window
    int val = 0;
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    if (!seen[val]) {
        seen[val] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        // Remove the leftmost bit, add the rightmost bit
        val = ((val << 1) & (total - 1)) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true;
        }
    }

    return count == total;
}

