public int minInsertions(String s) {
    int minInsertions = 0;
    int openNeeded = 0;

    for (char c : s.toCharArray()) {
        if (c == ')') {
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                minInsertions++;
            }
        } else {
            openNeeded++;
        }
    }

    minInsertions += openNeeded;
    return minInsertions;
}

public int minInsertions(String s) {
    int openNeeded = 0; // number of '(' needed to balance the current open count
    int result = 0;     // total insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openNeeded++;
        } else {
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                result++; // need to insert '(' to balance this ')'
            }
        }
    }

    result += openNeeded; // insert ')'s to close all remaining open '('
    return result;
}

public int minInsertions(String s) {
    int openNeeded = 0;
    int totalInsertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openNeeded++;
        } else {
            // c is ')'
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                // Need to insert a '(' before this ')'
                totalInsertions++;
            }
        }
    }

    // openNeeded is the number of unmatched '(' that need matching ')'
    totalInsertions += openNeeded;

    return totalInsertions;
}

public int minInsertions(String s) {
        int insertions = 0;
        int balance = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                balance++;
            } else {
                balance--;
                if (balance < 0) {
                    balance++;
                    insertions++;
                }
            }
        }

        return insertions + balance;
    }

public int minInsertions(String s) {
        int leftToInsert = 0;
        int rightAvailable = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                rightAvailable++;
            } else {
                if (rightAvailable > 0) {
                    rightAvailable--;
                } else {
                    leftToInsert++;
                }
            }
        }

        return leftToInsert + rightAvailable;
    }

