        // So the target value for each element is n^2 / n = n
        // The number of operations is the total amount of "excess" that must be moved
        // from elements greater than n to elements less than n.
        // For an element arr[i] = 2i+1, the difference from n is (2i+1) - n.
        // If 2i+1 > n, we need to subtract (2i+1 - n) from that element.
        // The total operations is the sum of positive differences.

        // Alternatively, we can think of it as:
        // operations = sum_{i where arr[i] > n} (arr[i] - n)
        // arr[i] > n means 2i+1 > n, so i > (n-1)/2
        // For n=3: arr=[1,3,5], n=3. i=2: 2*2+1=5>3, diff=2. Total=2.
        // For n=6: arr=[1,3,5,7,9,11], n=6. 
        //   i=3:7>6 diff=1, i=4:9>6 diff=3, i=5:11>6 diff=5. Total=1+3+5=9.

        // We can compute this with a loop, or derive a closed form.
        // Let's use a loop for clarity, but we can also compute directly.
        // The indices i where 2i+1 > n are i from ceil(n/2) to n-1? 
        // 2i+1 > n => i > (n-1)/2.
        // For n odd, n=2k+1: (n-1)/2 = k. i > k => i from k+1 to 2k.
        //   arr[i] for i=k+1..2k: 2(k+1)+1=2k+3, ..., 2(2k)+1=4k+1.
        //   target = n = 2k+1.
        //   diffs: (2k+3-(2k+1))=2, (2k+5-(2k+1))=4, ... , (4k+1-(2k+1))=2k.
        //   Sum = 2+4+...+2k = 2*(1+2+...+k) = 2*k*(k+1)/2 = k*(k+1).
        //   For n=3, k=1: 1*2=2. Correct.

        // For n even, n=2k: (n-1)/2 = (2k-1)/2 = k-0.5. i > k-0.5 => i from k to 2k-1.
        //   arr[i] for i=k..2k-1: 2k+1, 2k+3, ..., 4k-1.
        //   target = 2k.
        //   diffs: (2k+1-2k)=1, (2k+3-2k)=3, ..., (4k-1-2k)=2k-1.
        //   Sum = 1+3+...+(2k-1) = k^2.
        //   For n=6, k=3: 3^2=9. Correct.

        // So we can compute directly:
        if (n % 2 == 0) {
            int k = n / 2;
            return k * k;
        } else {
            int k = (n - 1) / 2;
            return k * (k + 1);
        }
    }

public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for 0 <= i < n
    // We want to make all elements equal to the average.
    // The average of the arithmetic progression 1, 3, 5, ..., 2n-1 is n.
    // So we want to make all elements equal to n.

    // The number of operations needed is the sum of |arr[i] - n| for i where arr[i] < n,
    // which equals the sum of (n - arr[i]) for i where arr[i] < n.
    // Alternatively, since the array is symmetric around n, we can just compute the sum
    // of positive differences from the median (which is the mean here).

    // For i from 0 to n-1:
    // arr[i] = 2*i + 1
    // We need to balance arr[i] to n.
    // The total amount we need to transfer is sum_{i: arr[i] < n} (n - arr[i])
    // This is equivalent to sum_{i: arr[i] > n} (arr[i] - n)

    // Let's compute the sum of differences for i where 2*i+1 < n.
    // 2*i + 1 < n => i < (n-1)/2

    long operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < n) {
            operations += (n - val);
        }
    }

    return (int) operations;
}

public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i from 0 to n-1.
    // We need to make all elements equal. The target value is the average of all elements.
    // Since the array is 1, 3, 5, ..., 2n-1, the sum is n * (first + last) / 2 = n * (1 + 2n - 1) / 2 = n * 2n / 2 = n^2.
    // So the average is n^2 / n = n.
    // Each operation moves 1 unit from one element to another. The total number of units that need to move is the sum of absolute differences from the target, but since each move reduces the total difference by 2 (1 from source, 1 to destination), the number of operations is half the sum of absolute differences.
    // Alternatively, we can think: the total "excess" on one side must equal the total "deficit" on the other. The number of operations is the total excess (or total deficit).
    // The target is n. For each i, the difference is |arr[i] - n| = |2i + 1 - n|.
    // The total operations is the sum of positive differences (or half the sum of absolute differences, but since the sum of absolute differences is even, we can just sum the absolute differences and divide by 2, or equivalently sum the differences where arr[i] > n, which equals the sum where arr[i] < n).
    // Let's compute the sum of |2i + 1 - n| for i from 0 to n-1, then divide by 2.

    long totalDiff = 0;
    for (int i = 0; i < n; i++) {
        int arrI = 2 * i + 1;
        totalDiff += Math.abs(arrI - n);
    }

    return (int) (totalDiff / 2);
}

