public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        twos |= (ones & num);
        ones ^= num;
        int threes = ~(ones & twos);
        ones &= threes;
        twos &= threes;
    }

    return ones;
}

