    if (low > high) {
        return result;
    }

    // BFS approach to generate all possible stepping numbers
    Queue<Long> queue = new LinkedList<>();

    // Start with numbers 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();

        // If current is within range, add to result
        if (current >= low && current <= high) {
            result.add((int) current);
        }

        // If current exceeds high, we can stop exploring further
        if (current > high) {
            continue;
        }

        // Get the last digit
        long lastDigit = current % 10;

        // Try adding lastDigit - 1
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }

        // Try adding lastDigit + 1
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    return result;
}

