public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean isNegative = n < 0;
    int absN = Math.abs(n);

    String numStr = String.valueOf(absN);
    StringBuilder result = new StringBuilder();

    int len = numStr.length();
    for (int i = 0; i < len; i++) {
        result.append(numStr.charAt(i));
        // Add separator if there are more digits and current position is at every 3rd from the end
        if (i != len - 1 && (len - i - 1) % 3 == 0) {
            result.append('.');
        }
    }

    if (isNegative) {
        result.insert(0, '-');
    }

    return result.toString();
}

