public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }

    // Use the cross product to determine if the three points are collinear
    // Given three points A, B, C, they are collinear if (B - A) x (C - A) = 0
    int ax = points[0][0], ay = points[0][1];
    int bx = points[1][0], by = points[1][1];
    int cx = points[2][0], cy = points[2][1];

    // Cross product of vectors AB and AC
    // AB = (bx - ax, by - ay)
    // AC = (cx - ax, cy - ay)
    int cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);

    // If cross product is 0, points are collinear (not a boomerang)
    // A boomerang requires the three points to not be collinear and all distinct
    return cross != 0;
}

