public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
        }
    }

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    String sorted = s.chars().sorted().mapToObj(c -> (char) c).map(String::valueOf).collect(java.util.stream.Collectors.joining());
    int maxEnergy = 0;
    int current = 0;
    char prev = 0;

    for (int i = 0; i < sorted.length(); i++) {
        char c = sorted.charAt(i);
        if (c == prev) {
            current++;
        } else {
            current = 1;
        }
        if (current > maxEnergy) {
            maxEnergy = current;
        }
        prev = c;
    }

    return maxEnergy;
}

