public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    long current = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        // If we can go deeper (multiply by 10 and still within range)
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            // Else, move to next sibling or go up to parent's next sibling
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

