public static List<Integer> lexicalOrder(int n) throws IllegalArgumentException {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    List<Integer> result = new ArrayList<>();
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current = current / 10;
                if (current == 0) {
                    break;
                }
            }
            if (current > 0) {
                current++;
            }
        }
    }
    return result;
}

