                current /= 10;
            }
            current += 1;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
        if (nums == null) {
            return 0;
        }

        java.util.Set<Integer> seen = new java.util.HashSet<>();
        java.util.Set<Integer> uniques = new java.util.HashSet<>();

        for (int num : nums) {
            if (!seen.add(num)) {
                uniques.remove(num);
            } else {
                uniques.add(num);
            }
        }

        int sum = 0;
        for (int num : uniques) {
            sum += num;
        }

        return sum;
    }

public static int calculateUniqueSum(int[] nums) {
        if (nums == null) {
            return 0;
        }
        java.util.Set<Integer> uniqueElements = new java.util.HashSet<>();
        java.util.Set<Integer> allElements = new java.util.HashSet<>();
        for (int num : nums) {
            allElements.add(num);
        }
        // First pass: add all elements
        for (int num : nums) {
            uniqueElements.add(num);
        }
        // We need elements that appear exactly once
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }
        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return sum;
    }

