public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int remainder = i - j * j;
            if (dp[remainder] + 1 < dp[i]) {
                dp[i] = dp[remainder] + 1;
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }

    // If n is 0, we need 0 perfect squares
    if (n == 0) {
        return 0;
    }

    // Generate all perfect squares up to n
    java.util.List<Integer> squares = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
    }

    // DP approach: dp[i] = minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (square > i) {
                break;
            }
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Check if n is a perfect square
    if (isPerfectSquare(n)) {
        return 1;
    }

    // Check if n can be expressed as a sum of two perfect squares
    for (int i = 1; i * i < n; i++) {
        if (isPerfectSquare(n - i * i)) {
            return 2;
        }
    }

    // Check if n can be expressed as a sum of three perfect squares
    // A number cannot be expressed as a sum of 3 squares if it's of the form 4^k(8m+7)
    if (canBeSumOfThreeSquares(n)) {
        return 3;
    }

    // Otherwise, it must be a sum of four perfect squares
    return 4;
}

