public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] chars = s.toCharArray();
    int start = 0;
    int n = chars.length;

    for (int i = 0; i <= n; i++) {
        if (i == n || chars[i] == ' ') {
            // Reverse the word from start to i-1
            reverse(chars, start, i - 1);
            start = i + 1;
        }
    }

    return new String(chars);
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Split by spaces, preserving empty strings from multiple spaces
    String[] words = s.split(" ", -1);
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        // Reverse the word character by character
        StringBuilder reversedWord = new StringBuilder();
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord.append(word.charAt(j));
        }
        result.append(reversedWord.toString());

        // Add space if not the last element
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

